#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/tc_util.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define MAIL_LEN 64
#define HIGH_PRIO 1
#define LOW_PRIO 8

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(high_stack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(low_stack, STACK_SIZE);
static struct k_thread tdata, high_tdata, low_tdata;
static struct k_mbox mbox, multi_tmbox;
static k_tid_t receiver_tid, sender_tid;
static struct k_sem sync_sem;

static enum mmsg_type {
	PUT_GET_NULL = 0,
	TARGET_SOURCE,
	MAX_MSG_TYPE
} info_type;

static char mail[MAIL_LEN] = "send performance test data";

static voidcleanup_resources(void)
{
	k_thread_abort(&tdata);
	k_thread_abort(&high_tdata);
	k_thread_abort(&low_tdata);
}

static void msg_sender(struct k_mbox *pmbox, k_timeout_t timeout)
{
	struct k_mbox_msg mmsg;

	(void)memset(&mmsg, 0, sizeof(mmsg));

	switch (info_type) {
	case PUT_GET_NULL:
		/* mbox sync put empty message */
		mmsg.info = PUT_GET_NULL;
		mmsg.size = 0;
		mmsg.tx_data = NULL;

		k_mbox_put(pmbox, &mmsg, timeout);
		break;
	case TARGET_SOURCE:
		/* mbox sync put a buffer */
		mmsg.info = TARGET_SOURCE;
		mmsg.size = sizeof(mail);
		mmsg.tx_data = mail;
		mmsg.tx_target_thread = receiver_tid;

		k_mbox_put(pmbox, &mmsg, timeout);
		break;
	default:
		break;
	}
}

static void msg_receiver(struct k_mbox *pmbox, k_tid_t thd_id,
			 k_timeout_t timeout)
{
	struct k_mbox_msg mmsg;
	char rxdata[MAIL_LEN];

	switch (info_type) {
	case PUT_GET_NULL:
		mmsg.size = sizeof(rxdata);
		mmsg.rx_source_thread = thd_id;

		/*unmatched, should return fail*/
		if (K_TIMEOUT_EQ(timeout, K_NO_WAIT)) {
			zassert_true(k_mbox_get(pmbox, &mmsg, rxdata,
						timeout) < 0, NULL);
		} else {
			zassert_true(k_mbox_get(pmbox, &mmsg, rxdata,
						timeout) == 0, NULL);
		}
		break;
	case TARGET_SOURCE:
		mmsg.size = sizeof(rxdata);
		mmsg.rx_source_thread = thd_id;

		zassert_true(k_mbox_get(pmbox, &mmsg, rxdata,
					timeout) == 0, NULL);
		zassert_equal(memcmp(rxdata, mail, MAIL_LEN), 0,
			      "rx data error");
		break;
	default:
		break;
	}
}

static void test_thread(void *p1, void *p2, void *p3)
{
	msg_sender((struct k_mbox *)p1, K_FOREVER);
}

static void receiver_high_prio(void *p1, void *p2, void *p3)
{
	struct k_mbox_msg mmsg;
	char rxdata[MAIL_LEN];

	mmsg.size = sizeof(rxdata);
	mmsg.rx_source_thread = K_ANY;
	zassert_true(k_mbox_get(&multi_tmbox, &mmsg, rxdata,
				K_FOREVER) == 0, NULL);

	k_sem_give(&sync_sem);
}

static void receiver_low_prio(void *p1, void *p2, void *p3)
{
	struct k_mbox_msg mmsg;
	char rxdata[MAIL_LEN];

	mmsg.size = sizeof(rxdata);
	mmsg.rx_source_thread = K_ANY;
	zassert_true(k_mbox_get(&multi_tmbox, &mmsg, rxdata,
				K_FOREVER) == 0, NULL);

	k_sem_give(&sync_sem);
}

/*Arrange a message queue that has at least two messages queued,
 *having different priorities.
 *Wait by using k_mbox_get().
 *Verify that the message received matches the highest-priority
 *sender waiting.
 */
ZTEST(mbox_usage, test_multi_thread_mbox_get)
{
	struct k_mbox_msg mmsg;
	static char data[2][MAIL_LEN] = {"send high prio data",
					 "send low prio data"};

	k_sem_reset(&sync_sem);

	/*Create two threads of different prio waiting for msg*/
	k_thread_create(&low_tdata, low_stack, STACK_SIZE,
			receiver_low_prio, NULL, NULL, NULL,
			LOW_PRIO, 0, K_NO_WAIT);

	k_thread_create(&high_tdata, high_stack, STACK_SIZE,
			receiver_high_prio, NULL, NULL, NULL,
			HIGH_PRIO, 0, K_NO_WAIT);

	mmsg.info = 0;
	mmsg.size = sizeof(data[0]);
	mmsg.tx_data = data[0];
	mmsg.tx_target_thread = K_ANY;
	k_mbox_put(&multi_tmbox, &mmsg, K_FOREVER);

	k_sem_take(&sync_sem, K_FOREVER);

	mmsg.info = 1;
	mmsg.size = sizeof(data[1]);
	mmsg.tx_data = data[1];
	mmsg.tx_target_thread = K_ANY;
	k_mbox_put(&multi_tmbox, &mmsg, K_FOREVER);

	k_sem_take(&sync_sem, K_FOREVER);

	voidcleanup_resources();
}

ZTEST(mbox_usage, test_mbox_put_get_null)
{
	info_type = PUT_GET_NULL;

	/*create sender thread to send msg*/
	sender_tid = k_thread_create(&tdata, tstack, STACK_SIZE,
				     test_thread, &mbox, NULL, NULL,
				     K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	/*give some time to make sure msg was sent*/
	k_sleep(K_MSEC(20));

	/*set receiver tid unmatched with sender's, and give K_NO_WAIT
	 *Wait by using k_mbox_get().
	 *Verify that the call returns immediately with an error.
	 */
	msg_receiver(&mbox, receiver_tid, K_NO_WAIT);

	/*receive the message which was sent at the beginning of test*/
	msg_receiver(&mbox, K_ANY, K_MSEC(2));

	k_thread_abort(sender_tid);
}

ZTEST(mbox_usage, test_mbox_target_source)
{
	info_type = TARGET_SOURCE;

	receiver_tid = k_current_get();
	sender_tid = k_thread_create(&tdata, tstack, STACK_SIZE,
				     test_thread, &mbox, NULL, NULL,
				     K_PRIO_PREEMPT(0), 0, K_NO_WAIT);
	msg_receiver(&mbox, sender_tid, K_MSEC(2));

	k_thread_abort(sender_tid);

	/* point to current thread Tid */
	receiver_tid = k_current_get();
	sender_tid = k_thread_create(&tdata, tstack, STACK_SIZE,
				     test_thread, &mbox, NULL, NULL,
				     K_PRIO_PREEMPT(0), 0, K_NO_WAIT);
	msg_receiver(&mbox, K_ANY, K_FOREVER);

	k_thread_abort(sender_tid);
}

void *mbox_usage_setup(void)
{
	k_mbox_init(&mbox);
	k_mbox_init(&multi_tmbox);
	k_sem_init(&sync_sem, 0, 2);

	return NULL;
}

ZTEST_SUITE(mbox_usage, NULL, mbox_usage_setup, NULL, NULL, NULL);
